import{H as e,V as t,et as n,j as r}from"./chunks/framework.ByEJxCeM.js";import"./chunks/assets.B5FjAcX4.js";var i=JSON.parse(`{"title":"依赖管理","description":"","frontmatter":{},"headers":[],"relativePath":"java/maven/dependency-management.md","filePath":"java/maven/dependency-management.md"}`),a={name:`java/maven/dependency-management.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="依赖管理" tabindex="-1">依赖管理 <a class="header-anchor" href="#依赖管理" aria-label="Permalink to “依赖管理”">​</a></h1><h2 id="依赖配置" tabindex="-1">依赖配置 <a class="header-anchor" href="#依赖配置" aria-label="Permalink to “依赖配置”">​</a></h2><h3 id="基本配置" tabindex="-1">基本配置 <a class="header-anchor" href="#基本配置" aria-label="Permalink to “基本配置”">​</a></h3><p>依赖：指当前项目运行所需要的jar包。一个项目中可以引入多个依赖：</p><p>例如：在当前工程中，我们需要用到logback来记录日志，此时就可以在maven工程的pom.xml文件中，引入logback的依赖。具体步骤如下：</p><ol><li><p>在pom.xml中编写<code>&lt;dependencies&gt;</code>标签</p></li><li><p>在<code>&lt;dependencies&gt;</code>标签中使用<code>&lt;dependency&gt;</code>引入坐标</p></li><li><p>定义坐标的 <code>groupId</code>、<code>artifactId</code>、<code>version</code></p></li></ol><div class="language-XML"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">XML</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    &lt;!-- 依赖 : spring-context --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.springframework&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;spring-context&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;6.1.4&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ol start="4"><li>点击刷新按钮，引入最新加入的坐标</li></ol><p>刷新依赖：保证每一次引入新的依赖，或者修改现有的依赖配置，都可以加入最新的坐标</p><p><img src="/blog-notes/assets/image-7.P--z3XGF.png" alt="imagepng" width="1478" height="733"></p><p><strong>注意事项：</strong></p><ol><li><p>如果引入的依赖，在本地仓库中不存在，将会连接远程仓库 / 中央仓库，然后下载依赖（这个过程会比较耗时，耐心等待）</p></li><li><p>如果不知道依赖的坐标信息，可以到mvn的中央仓库（<a href="https://mvnrepository" target="_blank" rel="noreferrer">https://mvnrepository</a>.com/）中搜索</p></li></ol><h3 id="查找依赖" tabindex="-1"><strong>查找依赖</strong> <a class="header-anchor" href="#查找依赖" aria-label="Permalink to “查找依赖”">​</a></h3><ol><li>利用中央仓库搜索的依赖坐标，以常见的logback-classic为例。</li></ol><p><img src="/blog-notes/assets/5.Cqd2KzKb.gif" alt="5gif" width="1368" height="931"></p><ol start="2"><li>利用IDEA工具搜索依赖，以常见的logback-classic为例。</li></ol><p><img src="/blog-notes/assets/6.C1f0qMoD.gif" alt="6gif" width="1257" height="866"></p><ol start="3"><li>熟练上手maven后，快速导入依赖，以常见的logback-classic为例。</li></ol><p><img src="/blog-notes/assets/7.qVdm90QR.gif" alt="7gif" width="1257" height="866"></p><h3 id="依赖传递" tabindex="-1">依赖传递 <a class="header-anchor" href="#依赖传递" aria-label="Permalink to “依赖传递”">​</a></h3><p>我们上面在pom.xml中配置了一项依赖，就是spring-context，但是我们通过右侧的maven面板可以看到，其实引入进来的依赖，并不是这一项，有非常多的依赖，都引入进来了。我们可以看到如下图所示：</p><p><img src="/blog-notes/assets/image-53.CVEoOgk9.png" alt="imagepng" width="1647" height="769"></p><p>为什么会出现这样的现象呢? 那这里呢，就涉及到maven中非常重要的一个特性，那就是Maven中的<strong>依赖传递</strong>。</p><p>所谓maven的依赖传递，指的就是如果在maven项目中，A 依赖了B，B依赖了C，C依赖了D，那么在A项目中，也会有C、D依赖，因为依赖会传递。</p><p>那如果，传递下来的依赖，在项目开发中，我们确实不需要，此时，我们可以通过Maven中的排除依赖功能，来将这个依赖排除掉。</p><h3 id="排除依赖" tabindex="-1">排除依赖 <a class="header-anchor" href="#排除依赖" aria-label="Permalink to “排除依赖”">​</a></h3><p><img src="/blog-notes/assets/image-22.znUUR83p.png" alt="imagepng" width="608" height="237"></p><ul><li><p>排除依赖：指主动断开依赖的资源，被排除的资源无需指定版本。</p></li><li><p>配置形式如下：</p></li></ul><div class="language-XML"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">XML</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.springframework&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;spring-context&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;6.1.4&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    &lt;!--排除依赖, 主动断开依赖的资源--&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">exclusions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">exclusion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;io.micrometer&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;micrometer-observation&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">exclusion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">exclusions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>依赖排除示例：</strong></p><ol><li>默认通过maven的依赖传递，传递下来了 <code>micrometer-observation</code> 的依赖。</li></ol><p><img src="/blog-notes/assets/image-38.h-DN_OSg.png" alt="imagepng" width="1652" height="760"></p><ol start="2"><li>加入排除依赖的配置之后，该依赖就被排除掉了。</li></ol><p><img src="/blog-notes/assets/image-6.B5D-Qm5W.png" alt="imagepng" width="1645" height="788"></p><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to “生命周期”">​</a></h2><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>Maven的生命周期就是为了对所有的构建过程进行抽象和统一。 描述了一次项目构建，经历哪些阶段。</p><p>在Maven出现之前，项目构建的生命周期就已经存在，软件开发人员每天都在对项目进行清理，编译，测试及部署。虽然大家都在不停地做构建工作，但公司和公司间、项目和项目间，往往使用不同的方式做类似的工作。</p><p>Maven从大量项目和构建工具中学习和反思，然后总结了一套高度完美的，易扩展的项目构建生命周期。这个生命周期包含了项目的清理，初始化，编译，测试，打包，集成测试，验证，部署和站点生成等几乎所有构建步骤。</p><p>Maven对项目构建的生命周期划分为3套（相互独立）：</p><p><img src="/blog-notes/assets/image-10.DdWhm7DB.png" alt="imagepng" width="1183" height="197"></p><ul><li><p>clean：清理工作。</p></li><li><p>default：核心工作。如：编译、测试、打包、安装、部署等。</p></li><li><p>site：生成报告、发布站点等。</p></li></ul><p>三套生命周期又包含哪些具体的阶段呢, 我们来看下面这幅图:</p><p><img src="/blog-notes/assets/image.Cl01p1LR.png" alt="imagepng" width="1089" height="513"></p><p>每套生命周期包含一些阶段（phase），阶段是有顺序的，后面的阶段依赖于前面的阶段。</p><p>我们看到这三套生命周期，里面有很多很多的阶段，这么多生命周期阶段，其实我们常用的并不多，主要关注以下几个：</p><ul><li><p>clean：移除上一次构建生成的文件</p></li><li><p>compile：编译项目源代码</p></li><li><p>test：使用合适的单元测试框架运行测试(junit)</p></li><li><p>package：将编译后的文件打包，如：jar、war等</p></li><li><p>install：安装项目到本地仓库</p></li></ul><p>Maven的生命周期是抽象的，这意味着生命周期本身不做任何实际工作。<strong>在Maven的设计中，实际任务（如源代码编译）都交由<strong><strong>插件</strong></strong>来完成。</strong></p><p><img src="/blog-notes/assets/image-25.DfkDmySw.png" alt="imagepng" width="1253" height="530"></p><p>IDEA工具为了方便程序员使用maven生命周期，在右侧的maven工具栏中，已给出快速访问通道。</p><p><img src="/blog-notes/assets/image-49.CTLxFY0d.png" alt="imagepng" width="1921" height="934"></p><ul><li><p>生命周期的顺序是：<code>clean</code> --&gt; <code>validate</code> --&gt; <code>compile</code> --&gt; <code>test</code> --&gt; <code>package</code> --&gt; <code>verify</code> --&gt; <code>install</code> --&gt; <code>site</code> --&gt; <code>deploy</code></p></li><li><p>我们需要关注的就是：<code>clean</code> --&gt; <code>compile</code> --&gt; <code>test</code> --&gt; <code>package</code> --&gt; <code>install</code></p></li></ul><p><strong>说明：</strong>在同一套生命周期中，我们在执行后面的生命周期时，前面的生命周期都会执行。</p><p><strong>思考：</strong>当运行package生命周期时，clean、compile生命周期会不会运行？</p><p>clean不会运行，compile会运行。 因为compile与package属于同一套生命周期，而clean与package不属于同一套生命周期。</p><h3 id="执行" tabindex="-1">执行 <a class="header-anchor" href="#执行" aria-label="Permalink to “执行”">​</a></h3><p>在日常开发中，当我们要执行指定的生命周期时，有两种执行方式：</p><ol><li><p>在idea工具右侧的maven工具栏中，选择对应的生命周期，双击执行</p></li><li><p>在DOS命令行中，通过maven命令执行</p></li></ol><p><strong>方式一：在idea中执行生命周期</strong></p><ul><li>选择对应的生命周期，双击执行</li></ul><p><img src="/blog-notes/assets/image-48.ChsM8wT8.png" alt="imagepng" width="1916" height="1004"></p><p>其他的生命周期都是类似的道理，双击运行即可。</p><p><strong>方式二：在命令行中执行生命周期</strong></p><ol><li>打开maven项目对应的磁盘目录</li></ol><p><img src="/blog-notes/assets/image-31.BseYkzO6.png" alt="imagepng" width="1212" height="799"></p><ol start="2"><li>在当前目录下打开CMD</li></ol><p><img src="/blog-notes/assets/image-52.Bvy2e1yX.png" alt="imagepng" width="1224" height="642"></p><p>类似的道理，我们也可以在命令执行：</p><ul><li><p>mvn compile</p></li><li><p>mvn test</p></li><li><p>mvn package</p></li><li><p>mvn install</p></li></ul>`,69)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};